-- d'argent passent en premier.

INSERT INTO `blog_posts` (`slug`,`category_id`,`title`,`excerpt`,`body`,`cover_emoji`,`author_name`,`meta_title`,`meta_description`,`status`,`reading_minutes`,`published_at`)
SELECT 'declarer-ses-gains-en-ligne-impots',2,'Déclarer ses gains en ligne aux impôts : ce que dit la loi française','Deux événements, deux traitements. Ce qui est clair, ce qui ne l\'est pas, et le seul conseil valable partout.','<p>Quelques euros gagnés en ligne, faut-il les déclarer ? La question revient constamment et les réponses trouvées sur internet sont souvent péremptoires et fausses. Voici ce que dit le cadre français, et surtout où passe la frontière entre ce qui est clair et ce qui ne l\'est pas.</p>\n\n<p class=\"wt-note\"><em>Cet article donne des informations générales, à jour à sa date de publication. Il ne remplace pas l\'avis d\'un professionnel ni les indications de l\'administration fiscale, seules à faire foi pour votre situation.</em></p>\n\n<h2>Le principe de départ</h2>\n\n<p>En France, les revenus sont imposables par principe. Il n\'existe pas de règle générale exonérant « les petits montants gagnés sur internet ». Les seuils que vous croiserez concernent des dispositifs précis, pas une dispense globale.</p>\n\n<p>Cela dit, imposable ne signifie pas nécessairement imposé : selon votre situation d\'ensemble, l\'impôt dû peut être nul. Mais la déclaration, elle, reste une obligation distincte du paiement.</p>\n\n<h2>Deux événements différents, deux traitements</h2>\n\n<p>C\'est le point que la plupart des articles confondent, et il structure tout le reste.</p>\n\n<p><strong>Premier événement : vous recevez une rémunération.</strong> Vous accomplissez des tâches, on vous verse une contrepartie. Peu importe qu\'elle soit versée en euros ou en crypto : c\'est un revenu d\'activité, et sa catégorie dépend de la nature et de la régularité de votre activité.</p>\n\n<p><strong>Second événement : vous vendez la crypto reçue.</strong> Si vous avez été payé en bitcoin et que vous le revendez contre des euros plus tard, la différence de valeur entre la réception et la vente relève du régime des cessions d\'actifs numériques.</p>\n\n<p>Ces deux événements ne se déclarent pas au même endroit et ne suivent pas les mêmes règles. Confondre les deux est l\'erreur la plus fréquente.</p>\n\n<h2>Le régime des cessions d\'actifs numériques</h2>\n\n<p>Pour un particulier qui cède occasionnellement des crypto-actifs, la plus-value est soumise au prélèvement forfaitaire unique. Son taux a changé : la loi de financement de la sécurité sociale pour 2026 a porté les prélèvements sociaux sur les revenus du capital de 17,2 % à 18,6 %.</p>\n\n<p>Le taux global est donc de <strong>31,4 %</strong> en 2026 — 12,8 % d\'impôt sur le revenu et 18,6 % de prélèvements sociaux — contre 30 % auparavant. L\'option pour le barème progressif reste possible, et elle est souvent plus favorable si vous êtes faiblement imposé.</p>\n\n<h2>Le seuil de 305 euros</h2>\n\n<p>Vous le verrez cité partout, souvent mal. Il existe une exonération d\'imposition lorsque le total annuel des cessions ne dépasse pas 305 euros.</p>\n\n<p>Attention à ce qu\'il signifie exactement : c\'est le total des <strong>cessions</strong>, pas des plus-values, et l\'exonération porte sur l\'imposition, <strong>pas sur la déclaration</strong>. Rester sous ce seuil ne dispense donc pas de remplir les cases correspondantes.</p>\n\n<h2>La déclaration des comptes à l\'étranger</h2>\n\n<p>Point souvent ignoré, et sans rapport avec vos gains : si vous détenez un compte d\'actifs numériques ouvert auprès d\'un service établi hors de France, il doit être déclaré, à l\'aide du formulaire 3916-bis. Un formulaire par compte.</p>\n\n<p>Cette obligation existe même sans aucune opération imposable, et même si le compte a été fermé en cours d\'année. Les comptes chez des microwallets et des plateformes d\'échange non françaises entrent typiquement dans ce cadre.</p>\n\n<h2>Ce que je ne peux pas vous dire</h2>\n\n<p>Soyons honnêtes sur les limites de cet article. La qualification exacte de revenus tirés de micro-tâches — et le régime applicable selon leur régularité et leur montant — dépend de votre situation personnelle, et l\'administration apprécie au cas par cas.</p>\n\n<p>Quiconque vous affirme « en dessous de X euros vous n\'avez rien à faire » vous donne une certitude qu\'il n\'a pas. Pour un montant modeste et occasionnel, le sujet reste généralement simple ; dès que l\'activité devient régulière et significative, la question mérite d\'être posée à un professionnel ou directement à votre centre des finances publiques.</p>\n\n<h2>Le seul conseil qui vaut dans tous les cas</h2>\n\n<p>Tenez un relevé. Une simple feuille de calcul avec la date, le montant, la devise et la contrepartie en euros au moment de l\'opération.</p>\n\n<p>Cela prend deux minutes par mois et vous épargne des heures de reconstitution le jour où la question se pose — que ce soit pour déclarer, pour justifier, ou simplement pour savoir où vous en êtes. C\'est aussi la seule façon de calculer une plus-value : sans le prix d\'acquisition, le calcul est impossible.</p>\n','📋','Équipe Wintaskly','Déclarer ses gains en ligne aux impôts : ce que dit la loi française','Deux événements, deux traitements. Ce qui est clair, ce qui ne l\'est pas, et le seul conseil valable partout.','published',8,'2026-10-06 07:00:00'
 WHERE NOT EXISTS (SELECT 1 FROM (SELECT 1) x WHERE EXISTS (SELECT 1 FROM `blog_posts` WHERE `slug`='declarer-ses-gains-en-ligne-impots'));

