INSERT INTO `blog_posts` (`slug`,`category_id`,`title`,`excerpt`,`body`,`cover_emoji`,`author_name`,`meta_title`,`meta_description`,`status`,`reading_minutes`,`published_at`)
SELECT 'seuil-305-euros-crypto',2,'Le seuil de 305 € : ce qu\'il exonère et ce qu\'il n\'exonère pas','Trois mots mal compris dans une seule phrase. Et les deux obligations que ce seuil ne couvre pas.','<p>Le seuil de 305 euros revient dans toutes les discussions sur la fiscalité des cryptomonnaies, presque toujours mal compris. Voici ce qu\'il couvre exactement — et surtout ce qu\'il ne couvre pas.</p>\n\n<p class=\"wt-note\"><em>Informations générales, à jour à la date de publication. Seules les indications de l\'administration fiscale font foi pour votre situation.</em></p>\n\n<h2>Ce que dit la règle</h2>\n\n<p>Lorsque le montant total de vos cessions d\'actifs numériques sur l\'année n\'excède pas 305 euros, la plus-value réalisée est exonérée d\'imposition.</p>\n\n<p>Trois mots comptent dans cette phrase, et chacun est source de confusion.</p>\n\n<h2>« Cessions », pas « plus-values »</h2>\n\n<p>C\'est l\'erreur la plus fréquente. Le seuil porte sur le <strong>montant total cédé</strong>, pas sur le gain réalisé.</p>\n\n<p>Un exemple. Vous vendez pour 400 euros de crypto que vous aviez acquis pour 380 euros. Votre plus-value est de 20 euros — bien en dessous de 305. Mais vos cessions s\'élèvent à 400 euros : le seuil est dépassé, et l\'exonération ne s\'applique pas.</p>\n\n<p>Retenez la formule : on regarde ce qui sort, pas ce qu\'on a gagné dessus.</p>\n\n<h2>« Total annuel », pas « par opération »</h2>\n\n<p>Le seuil s\'apprécie sur l\'ensemble de l\'année civile, toutes cessions confondues.</p>\n\n<p>Dix cessions de 50 euros font 500 euros de cessions annuelles. Chacune est modeste, le total ne l\'est pas. Beaucoup se croient couverts parce qu\'aucune opération isolée ne dépasse le seuil.</p>\n\n<h2>« Exonération d\'imposition », pas de déclaration</h2>\n\n<p>Le point le plus souvent ignoré, et le plus lourd de conséquences.</p>\n\n<p>L\'exonération porte sur l\'impôt. Elle ne dispense pas de déclarer. Vos opérations doivent figurer dans le formulaire prévu, même si le total reste sous le seuil et même si aucun impôt n\'est dû.</p>\n\n<p>Autrement dit : rester sous 305 euros vous évite de payer, pas de remplir.</p>\n\n<h2>Ce que le seuil ne concerne pas du tout</h2>\n\n<p>Deux obligations restent entièrement indépendantes de lui.</p>\n\n<p><strong>La déclaration d\'un compte détenu à l\'étranger.</strong> Si vous avez un compte d\'actifs numériques auprès d\'un service établi hors de France, il doit être déclaré, quel que soit son solde et même sans aucune opération. Le seuil de 305 euros n\'a aucun effet ici.</p>\n\n<p><strong>Les revenus d\'activité.</strong> Une rémunération perçue en contrepartie d\'un travail n\'est pas une cession d\'actif numérique. Elle relève d\'une autre catégorie, avec ses propres règles. Le seuil ne s\'y applique pas.</p>\n\n<p>C\'est cette confusion qui produit la plupart des affirmations fausses trouvées en ligne : « en dessous de 305 euros vous n\'avez rien à faire » mélange trois obligations distinctes.</p>\n\n<h2>Ce que cela signifie pour des micro-gains</h2>\n\n<p>Si vous retirez de petites sommes en crypto sans jamais les revendre contre des euros, vous n\'avez réalisé aucune cession. Le seuil ne vous concerne pas, faute d\'opération à comptabiliser.</p>\n\n<p>Si vous les revendez, faites simplement le total de ce que vous avez cédé dans l\'année. C\'est ce chiffre-là qu\'il faut comparer à 305 euros — pas votre gain, pas votre solde, pas le montant d\'une opération isolée.</p>\n\n<h2>Le réflexe utile</h2>\n\n<p>Tenez un relevé de vos cessions au fil de l\'eau : date, montant cédé, contrepartie en euros. Vous saurez à tout moment où vous en êtes par rapport au seuil, sans avoir à reconstituer une année entière au printemps.</p>\n\n<p>Et si votre situation dépasse le cas simple, posez la question à votre centre des finances publiques. C\'est gratuit, et cela vaut mieux qu\'un article — y compris celui-ci.</p>\n','📊','Équipe Wintaskly','Le seuil de 305 € : ce qu\'il exonère et ce qu\'il n\'exonère pas','Trois mots mal compris dans une seule phrase. Et les deux obligations que ce seuil ne couvre pas.','published',7,'2026-10-16 07:00:00'
